  def observation_assessment_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var observation_assessment: Observation_Sortie_Eligibility_Supervisor.SingleEquipmentAssessment = $

  def put_observation_assessment(value : Observation_Sortie_Eligibility_Supervisor.SingleEquipmentAssessment) : Unit = {
    Contract(
      Modifies(observation_assessment),
      Ensures(
        observation_assessment == value
